package com.aistock.notification.alert;
import static com.aistock.notification.alert.AlertRecords.*;import java.time.*;import java.sql.Timestamp;import java.util.UUID;
public final class NotificationPreferenceService {
 private final AlertRuleRepository repo;private final Clock clock;private final java.util.function.Supplier<String> availability;public NotificationPreferenceService(AlertRuleRepository repo,Clock clock){this(repo,clock,()->"NOT_ENABLED");}public NotificationPreferenceService(AlertRuleRepository repo,Clock clock,java.util.function.Supplier<String> availability){this.repo=repo;this.clock=clock;this.availability=availability;}
 public Preference get(UUID owner){var rows=repo.jdbc().queryForList("select email_enabled,revision from notification_preference where user_id=?",owner.toString());return rows.isEmpty()?new Preference(false,0,availability.get()):new Preference(Boolean.TRUE.equals(rows.get(0).get("email_enabled")),((Number)rows.get(0).get("revision")).longValue(),availability.get());}
 public Preference patch(UUID owner,Long revision,Boolean enabled,boolean emailVerified){if(revision==null||revision<0||enabled==null||enabled&&!emailVerified)throw AlertRuleService.invalid();return repo.locked(owner,()->{var old=get(owner);if(old.revision()!=revision)throw AlertRuleService.conflict("ALERT_REVISION_CONFLICT");repo.jdbc().update("insert into notification_preference(user_id,email_enabled,revision,updated_at) values(?,?,?,?) on duplicate key update email_enabled=values(email_enabled),revision=values(revision),updated_at=values(updated_at)",owner.toString(),enabled,old.revision()+1,Timestamp.from(clock.instant()));return new Preference(enabled,old.revision()+1,availability.get());});}
}
